دالة ثنائي(ع) {
    متغير ن = ""
    إذا (ع == ٠) { ن = "٠" }
    وإلا {
        متغير عد = ع
        من_أجل (ي من ٣٠ إلى ٠ بخطوة -١) {
            متغير باقي = عد % ٢
            ن = نص(باقي) + ن
            عد = عد // ٢
        }
    }
    ارجع ن
}
```

